B.c2t=new A.ia("\u0627\u0644\u0628\u0635\u0645\u0629 \u0648Face ID","\u062a\u062a\u0645 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0627\u0644\u062d\u064a\u0648\u064a\u0629 \u062f\u0627\u062e\u0644 \u0646\u0638\u0627\u0645 \u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0647\u0627\u062a\u0641. \u0644\u0627 \u064a\u0633\u062a\u0644\u0645 ZaWolf HR \u0648\u0644\u0627 \u064a\u062e\u0632\u0646 \u0642\u0627\u0644\u0628 \u0627\u0644\u0628\u0635\u0645\u0629 \u0623\u0648 \u0635\u0648\u0631\u0629 \u0627\u0644\u0648\u062c\u0647. \u064a\u062d\u062a\u0641\u0638 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0641\u0642\u0637 \u0628\u0646\u062a\u064a\u062c\u0629 \u0646\u062c\u0627\u062d \u0623\u0648 \u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642 \u0639\u0646\u062f\u0645\u0627 \u062a\u0643\u0648\u0646 \u0644\u0627\u0632\u0645\u0629 \u0644\u0625\u062a\u0645\u0627\u0645 \u0627\u0644\u0639\u0645\u0644\u064a\u0629.")
B.c2m=new A.ia("\u0627\u0644\u0634\u0643\u0627\u0648\u0649 \u0645\u062c\u0647\u0648\u0644\u0629 \u0627\u0644\u0647\u0648\u064a\u0629","\u0639\u0646\u062f \u0627\u062e\u062a\u064a\u0627\u0631 \u0625\u0631\u0633\u0627\u0644 \u0634\u0643\u0648\u0649 \u0628\u0635\u0648\u0631\u0629 \u0645\u062c\u0647\u0648\u0644\u0629\u060c \u0644\u0627 \u064a\u0638\u0647\u0631 \u0627\u0633\u0645 \u0645\u0642\u062f\u0645\u0647\u0627 \u0644\u0644\u0645\u0631\u0627\u062c\u0639\u064a\u0646 \u0641\u064a \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0634\u0643\u0627\u0648\u0649. \u0642\u062f \u064a\u062d\u062a\u0641\u0638 \u0627\u0644\u0646\u0638\u0627\u0645 \u062f\u0627\u062e\u0644\u064a\u0627\u064b \u0628\u0645\u0639\u0631\u0641 \u062a\u0642\u0646\u064a \u0645\u062d\u062f\u0648\u062f \u0644\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u062e\u062f\u0645\u0629\u060c \u0648\u0645\u0646\u0639 \u0627\u0644\u0625\u0633\u0627\u0621\u0629\u060c \u0648\u062a\u0645\u0643\u064a\u0646 \u0645\u0642\u062f\u0645 \u0627\u0644\u0634\u0643\u0648\u0649 \u0645\u0646 \u0645\u062a\u0627\u0628\u0639\u0629 \u062d\u0627\u0644\u062a\u0647\u0627\u060c \u0648\u0642\u062f \u064a\u0637\u0644\u0639 \u0639\u0644\u064a\u0647 \u0645\u0633\u0624\u0648\u0644\u0648 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u062e\u0648\u0644\u0648\u0646 \u0639\u0646\u062f \u0648\u062c\u0648\u062f \u0627\u0644\u062a\u0632\u0627\u0645 \u0642\u0627\u0646\u0648\u0646\u064a \u0623\u0648 \u062d\u0627\u062f\u062b \u0623\u0645\u0646\u064a.")
